test "TensorCore integrateQSM" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();
    var tensor = try TensorCore.init(allocator, &[_]usize{2, 2}, .f64);
    defer tensor.deinit();
    var ctx1 = try allocator.alloc(f64, 2);
    ctx1[0] = 0.1;
    ctx1[1] = 0.2;
    var ctx2 = try allocator.alloc(f64, 2);
    ctx2[0] = 0.3;
    ctx2[1] = 0.4;
