const std = @import("std");
const math = std.math;
const mem = std.mem;
const testing = std.testing;
const Allocator = mem.Allocator;
const ArrayList = std.ArrayList;
const HashMap = std.HashMap;
const Random = std.rand.Random;
const DefaultPrng = std.rand.DefaultPrng;
const meta = @import("meta.zig");
const tokenizer = @import("tokenizer.zig");
const optimizer = @import("optimizer.zig");
const runtime = @import("runtime.zig");
const hardware = @import("hardware.zig");

const c = @cImport({
    @cInclude("math.h");
    @cInclude("complex.h");
});

pub const QSM = struct {
    allocator: Allocator,
    contexts: ArrayList(ArrayList(f64)),
    interference: f64,

    pub fn init(allocator: Allocator) QSM {
        return .{
            .allocator = allocator,
            .contexts = ArrayList(ArrayList(f64)).init(allocator),
            .interference = 0.0,
        };
    }

    pub fn deinit(self: *QSM) void {
        for (self.contexts.items) |*ctx| {
            ctx.deinit();
        }
        self.contexts.deinit();
    }

    pub fn multiplex(self: *QSM, synapse: f64, contexts: []const []const f64) !void {
        self.interference = 0.0;
        for (contexts) |ctx| {
            var phase: f64 = 0.0;
            var amp: f64 = 0.0;
            for (ctx) |c| {
                phase += c;
                amp += math.absFloat(c) / 10.0;
            }
            self.interference += math.sin(phase) * amp;
        }
        self.interference *= synapse;
    }

    pub fn getInterference(self: *const QSM) f64 {
        return self.interference;
    }
};

pub const MES = struct {
    allocator: Allocator,
    codec: *const fn (Allocator, []const u8) anyerror![]u8,
    condition: bool,

    pub fn init(allocator: Allocator) MES {
        return .{
            .allocator = allocator,
            .codec = &defaultCodec,
            .condition = false,
        };
    }

    pub fn deinit(self: *MES) void {
        _ = self;
    }

    pub fn selfOverwrite(self: *MES, cond: bool) void {
        self.condition = cond;
    }

    pub fn process(self: *MES, input: []const u8) ![]u8 {
        if (self.condition) {
            return try reverseString(self.allocator, input);
        } else {
            return try self.codec(self.allocator, input);
        }
    }

    fn defaultCodec(alloc: Allocator, s: []const u8) ![]u8 {
        return try alloc.dupe(u8, s);
    }

    fn reverseString(allocator: Allocator, s: []const u8) ![]u8 {
        const len = s.len;
        var result = try allocator.alloc(u8, len);
        var i: usize = 0;
        while (i < len) : (i += 1) {
            result[i] = s[len - 1 - i];
        }
        return result;
    }
};

pub const EHM = struct {
    allocator: Allocator,
    state: f64,
    reflection: []u8,

    pub fn init(allocator: Allocator) EHM {
        return .{
            .allocator = allocator,
            .state = 1.0,
            .reflection = &[_]u8{},
        };
    }

    pub fn deinit(self: *EHM) void {
        self.allocator.free(self.reflection);
    }

    pub fn update(self: *EHM, refl: []const u8) !void {
        self.allocator.free(self.reflection);
        self.reflection = try self.allocator.dupe(u8, refl);
        self.state *= 1.1;
    }

    pub fn getState(self: *const EHM) f64 {
        return self.state;
    }
};

pub const MXSI = struct {
    voltage: f64,
    temp: f64,
    conductance: f64,

    pub fn init() MXSI {
        return .{
            .voltage = 0.0,
            .temp = 300.0,
            .conductance = 0.0,
        };
    }

    pub fn compute(self: *MXSI, v: f64, t: f64) void {
        self.voltage = v;
        self.temp = t;
        self.conductance = v * (1.0 + t / 300.0);
    }

    pub fn getConductance(self: *const MXSI) f64 {
        return self.conductance;
    }
};

pub const CPS = struct {
    allocator: Allocator,
    thoughts: ArrayList([]u8),
    topology: ArrayList(struct { thought: []u8, phase: f64 }),

    pub fn init(allocator: Allocator) CPS {
        return .{
            .allocator = allocator,
            .thoughts = ArrayList([]u8).init(allocator),
            .topology = ArrayList(struct { thought: []u8, phase: f64 }).init(allocator),
        };
    }

    pub fn deinit(self: *CPS) void {
        for (self.thoughts.items) |t| {
            self.allocator.free(t);
        }
        self.thoughts.deinit();
        for (self.topology.items) |top| {
            self.allocator.free(top.thought);
        }
        self.topology.deinit();
    }

    pub fn addThought(self: *CPS, thought: []const u8) !void {
        const dup = try self.allocator.dupe(u8, thought);
        try self.thoughts.append(dup);
    }

    pub fn computeTopology(self: *CPS) !void {
        self.topology.clearAndFree();
        for (self.thoughts.items) |th| {
            const len = th.len;
            const phase = math.sqrt(@as(f64, @floatFromInt(len)));
            const dup_th = try self.allocator.dupe(u8, th);
            const top = .{ .thought = dup_th, .phase = phase };
            try self.topology.append(top);
        }
    }

    pub fn getTopology(self: *const CPS) []const struct { thought: []u8, phase: f64 } {
        return self.topology.items;
    }
};

pub const TensorCore = struct {
    allocator: Allocator,
    shape: []usize,
    data: []f64,
    dtype: DType,
    qsm: QSM,
    mes: MES,
    ehm: EHM,
    mxsi: MXSI,
    cps: CPS,
    tokenizer: tokenizer.Tokenizer,
    optimizer: optimizer.ZOOptimizer,
    runtime: runtime.Runtime,

    pub const DType = enum { f64, f32, i64, i32 };

    pub fn init(allocator: Allocator, shape: []const usize, dtype: DType) !TensorCore {
        var total_size: usize = 1;
        for (shape) |dim| {
            total_size *= dim;
        }
        var data = try allocator.alloc(f64, total_size);
        @memset(data, 0.0);
        var qsm = QSM.init(allocator);
        var mes = MES.init(allocator);
        var ehm = EHM.init(allocator);
        var mxsi = MXSI.init();
        var cps = CPS.init(allocator);
        var tok = try tokenizer.Tokenizer.init(allocator);
        var opt = optimizer.ZOOptimizer.init(allocator);
        var rt = runtime.Runtime.init(allocator);
        var tensor = TensorCore{
            .allocator = allocator,
            .shape = try allocator.dupe(usize, shape),
            .data = data,
            .dtype = dtype,
            .qsm = qsm,
            .mes = mes,
            .ehm = ehm,
            .mxsi = mxsi,
            .cps = cps,
            .tokenizer = tok,
            .optimizer = opt,
            .runtime = rt,
        };
        return tensor;
    }

    pub fn deinit(self: *TensorCore) void {
        self.qsm.deinit();
        self.mes.deinit();
        self.ehm.deinit();
        self.cps.deinit();
        self.tokenizer.deinit();
        self.optimizer.deinit();
        self.runtime.deinit();
        self.allocator.free(self.shape);
        self.allocator.free(self.data);
    }

    pub fn reshape(self: *TensorCore, new_shape: []const usize) !void {
        var old_total: usize = 1;
        for (self.shape) |dim| {
            old_total *= dim;
        }
        var new_total: usize = 1;
        for (new_shape) |dim| {
            new_total *= dim;
        }
        if (old_total != new_total) {
            return error.InvalidShape;
        }
        self.allocator.free(self.shape);
        self.shape = try self.allocator.dupe(usize, new_shape);
    }

    pub fn add(self: *TensorCore, other: *const TensorCore) !void {
        if (!self.shapeMatches(other)) return error.ShapeMismatch;
        for (self.data, other.data) |*val, o| {
            val.* += o;
        }
    }

    pub fn mul(self: *TensorCore, other: *const TensorCore) !void {
        if (!self.shapeMatches(other)) return error.ShapeMismatch;
        for (self.data, other.data) |*val, o| {
            val.* *= o;
        }
    }

    pub fn matmul(self: *TensorCore, other: *const TensorCore) !TensorCore {
        if (self.shape.len != 2 or other.shape.len != 2) return error.NotMatrix;
        if (self.shape[1] != other.shape[0]) return error.InvalidDimensions;
        const rows = self.shape[0];
        const cols = other.shape[1];
        const inner = self.shape[1];
        var result = try TensorCore.init(self.allocator, &[_]usize{ rows, cols }, .f64);
        var i: usize = 0;
        while (i < rows) : (i += 1) {
            var j: usize = 0;
            while (j < cols) : (j += 1) {
                var sum: f64 = 0.0;
                var k: usize = 0;
                while (k < inner) : (k += 1) {
                    sum += self.data[i * inner + k] * other.data[k * cols + j];
                }
                result.data[i * cols + j] = sum;
            }
        }
        return result;
    }

    pub fn softmax(self: *TensorCore, axis: usize) !void {
        if (self.shape.len != 2) return error.Not2D;
        const rows = self.shape[0];
        const cols = self.shape[1];
        if (axis > 1) return error.InvalidAxis;
        if (axis == 0) {
            var j: usize = 0;
            while (j < cols) : (j += 1) {
                var max_val: f64 = -math.inf(f64);
                var i: usize = 0;
                while (i < rows) : (i += 1) {
                    const val = self.data[i * cols + j];
                    if (val > max_val) max_val = val;
                }
                var exp_sum: f64 = 0.0;
                i = 0;
                while (i < rows) : (i += 1) {
                    const shifted = self.data[i * cols + j] - max_val;
                    const exp_val = math.exp(shifted);
                    self.data[i * cols + j] = exp_val;
                    exp_sum += exp_val;
                }
                const inv_sum = 1.0 / exp_sum;
                i = 0;
                while (i < rows) : (i += 1) {
                    self.data[i * cols + j] *= inv_sum;
                }
            }
        } else {
            var i: usize = 0;
            while (i < rows) : (i += 1) {
                var max_val: f64 = -math.inf(f64);
                var j: usize = 0;
                while (j < cols) : (j += 1) {
                    const val = self.data[i * cols + j];
                    if (val > max_val) max_val = val;
                }
                var exp_sum: f64 = 0.0;
                j = 0;
                while (j < cols) : (j += 1) {
                    const shifted = self.data[i * cols + j] - max_val;
                    const exp_val = math.exp(shifted);
                    self.data[i * cols + j] = exp_val;
                    exp_sum += exp_val;
                }
                const inv_sum = 1.0 / exp_sum;
                j = 0;
                while (j < cols) : (j += 1) {
                    self.data[i * cols + j] *= inv_sum;
                }
            }
        }
    }

    pub fn argmax(self: *TensorCore, axis: usize) !TensorCore {
        if (self.shape.len != 2) return error.Not2D;
        const rows = self.shape[0];
        const cols = self.shape[1];
        var result_shape = [1]usize{undefined};
        if (axis == 0) {
            result_shape[0] = cols;
        } else {
            result_shape[0] = rows;
        }
        var result = try TensorCore.init(self.allocator, &result_shape, .i64);
        const data_bytes = mem.sliceAsBytes(result.data);
        const ptr = @as([*]i64, @ptrCast(@alignCast(data_bytes.ptr)));
        if (axis == 0) {
            var j: usize = 0;
            while (j < cols) : (j += 1) {
                var max_idx: usize = 0;
                var max_val = self.data[0 * cols + j];
                var i: usize = 1;
                while (i < rows) : (i += 1) {
                    const val = self.data[i * cols + j];
                    if (val > max_val) {
                        max_val = val;
                        max_idx = i;
                    }
                }
                ptr[j] = @intCast(max_idx);
            }
        } else {
            var i: usize = 0;
            while (i < rows) : (i += 1) {
                var max_idx: usize = 0;
                var max_val = self.data[i * cols + 0];
                var j: usize = 1;
                while (j < cols) : (j += 1) {
                    const val = self.data[i * cols + j];
                    if (val > max_val) {
                        max_val = val;
                        max_idx = j;
                    }
                }
                ptr[i] = @intCast(max_idx);
            }
        }
        return result;
    }

    pub fn integrateQSM(self: *TensorCore, synapse: f64, contexts: [][]const f64) !void {
        try self.qsm.multiplex(synapse, contexts);
        const interf = self.qsm.getInterference();
        for (self.data) |*val| {
            val.* += interf;
        }
    }

    pub fn applyMES(self: *TensorCore, cond: bool, input_str: []const u8) !void {
        self.mes.selfOverwrite(cond);
        const processed = try self.mes.process(input_str);
        defer self.allocator.free(processed);
        if (processed.len > 0) {
            self.data[0] = @floatFromInt(processed[0]);
        }
    }

    pub fn reflectEHM(self: *TensorCore, refl: []const u8) !void {
        try self.ehm.update(refl);
        const state = self.ehm.getState();
        for (self.data) |*val| {
            val.* *= state;
        }
    }

    pub fn adjustMXSI(self: *TensorCore, v: f64, t: f64) void {
        self.mxsi.compute(v, t);
        const cond = self.mxsi.getConductance();
        for (self.data) |*val| {
            val.* *= cond;
        }
    }

    pub fn phaseCPS(self: *TensorCore, thoughts: [][]const u8) !void {
        self.cps.thoughts.clearRetainingCapacity();
        for (thoughts) |th| {
            try self.cps.addThought(th);
        }
        try self.cps.computeTopology();
        const topology = self.cps.getTopology();
        var i: usize = 0;
        while (i < topology.len and i < self.data.len) : (i += 1) {
            self.data[i] += topology[i].phase;
        }
    }

    pub fn tokenize(self: *TensorCore, text: []const u8) ![]usize {
        return try self.tokenizer.tokenize(text);
    }

    pub fn optimize(self: *TensorCore, params: []f64) !void {
        try self.optimizer.optimize(params);
    }

    pub fn run(self: *TensorCore, input: []f64) ![]f64 {
        return try self.runtime.run(input);
    }

    pub fn hardwareAccel(self: *TensorCore, data: []f64) ![]f64 {
        return try hardware.accelerate(data);
    }

    fn shapeMatches(self: *const TensorCore, other: *const TensorCore) bool {
        if (self.shape.len != other.shape.len) return false;
        for (self.shape, other.shape) |s, o| {
            if (s != o) return false;
        }
        return true;
    }
};

